UPDATE w16_rendezvous_match SET version=#{version}, first_accepted_at=#{firstAcceptedAt,jdbcType=BIGINT},
  second_accepted_at=#{secondAcceptedAt,jdbcType=BIGINT}, state=#{state}
WHERE id=#{id} AND first_ticket=#{firstTicket} AND second_ticket=#{secondTicket} AND public_place=#{publicPlace}
  AND expires_at=#{expiresAt} AND version=#{version}-1
  AND (first_accepted_at IS NULL OR first_accepted_at=#{firstAcceptedAt,jdbcType=BIGINT})
  AND (second_accepted_at IS NULL OR second_accepted_at=#{secondAcceptedAt,jdbcType=BIGINT})
